package com.stacklab;
import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.http.MediaType;import org.springframework.test.web.servlet.MockMvc;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"app.jwt.secret=test-only-secret-not-used-outside-tests-0123456789","spring.datasource.url=jdbc:h2:mem:auth-api-test;MODE=PostgreSQL;DB_CLOSE_DELAY=-1;DATABASE_TO_LOWER=TRUE"}) @AutoConfigureMockMvc class AuthApiIntegrationTest{@Autowired MockMvc mvc;
 @Test void registerLoginAndProtectedAccessFlow()throws Exception{String body="{\"name\":\"Test User\",\"email\":\"test@example.test\",\"password\":\"correct-horse-44\"}";mvc.perform(post("/api/auth/register").contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isCreated()).andExpect(jsonPath("$.user.role").value("EMPLOYEE"));String login="{\"email\":\"test@example.test\",\"password\":\"correct-horse-44\"}";String token=mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content(login)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString().replaceAll(".*\\\"token\\\":\\\"([^\\\"]+)\\\".*","$1");mvc.perform(get("/api/tasks").header("Authorization","Bearer "+token)).andExpect(status().isOk());}
 @Test void invalidRegistrationReturnsStructured400()throws Exception{mvc.perform(post("/api/auth/register").contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"\",\"email\":\"bad\",\"password\":\"x\"}")).andExpect(status().isBadRequest()).andExpect(jsonPath("$.status").value(400)).andExpect(jsonPath("$.path").value("/api/auth/register"));}
 @Test void unauthenticatedProtectedRouteReturns401()throws Exception{mvc.perform(get("/api/tasks")).andExpect(status().isUnauthorized());}}
